# Removes generated Android/Gradle build caches. They are what makes copying this
# folder fail with "file name too long": Gradle writes paths of 300-400+ characters
# inside node_modules (e.g. node_modules\expo-modules-core\android\build\.transforms\...),
# and Windows Explorer cannot copy anything past 260. They also record this folder's
# absolute path, so a moved copy fails CMake with "CMakeCache.txt directory ... is different".
# Everything removed is regenerated by the next Gradle build (first build ~2-3 min).
#
#   powershell -ExecutionPolicy Bypass -File scripts\clean-native-caches.ps1
#   powershell -ExecutionPolicy Bypass -File scripts\clean-native-caches.ps1 -ListOnly   # print, delete nothing
#
# Rules (never touches source, the keystore, release\, or JavaScript build\ folders):
#   * any .cxx / .gradle / .kotlin folder under android\ or node_modules\
#   * a build\ folder only when its parent holds build.gradle or build.gradle.kts
#     (node_modules packages such as @expo\config ship real JS in build\ - kept)
# Uses cmd's dir / rd, which handle paths past 260 characters on Windows PowerShell 5.1.

param([switch]$ListOnly)

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot

$scan = @('android', 'node_modules') | ForEach-Object { Join-Path $root $_ } | Where-Object { Test-Path -LiteralPath $_ }
$dirs = foreach ($s in $scan) { cmd /c "dir /s /b /ad `"$s`"" 2>$null }

$hits = New-Object System.Collections.Generic.List[string]
foreach ($d in ($dirs | Sort-Object)) {
  # Skip anything inside a folder already selected.
  if ($hits.Count -gt 0 -and $d.StartsWith($hits[$hits.Count - 1] + '\')) { continue }
  $name = Split-Path -Leaf $d
  $parent = Split-Path -Parent $d
  $isGradleCache = $name -in @('.cxx', '.gradle', '.kotlin')
  $isGradleBuild = $name -eq 'build' -and (
    (Test-Path -LiteralPath (Join-Path $parent 'build.gradle')) -or
    (Test-Path -LiteralPath (Join-Path $parent 'build.gradle.kts')))
  if ($isGradleCache -or $isGradleBuild) { $hits.Add($d) }
}
$expo = Join-Path $root '.expo'
if (Test-Path -LiteralPath $expo) { $hits.Add($expo) }

if ($ListOnly) { $hits; return }

foreach ($h in $hits) {
  cmd /c "rd /s /q `"\\?\$h`""
  if (Test-Path -LiteralPath $h) { throw "Could not remove $h (a build or editor may be using it)" }
  Write-Host ('removed ' + $h.Substring($root.Length + 1))
}

# Stop the Gradle daemon so no process keeps the old path open (best effort).
$gradlew = Join-Path $root 'android\gradlew.bat'
$jbr = 'C:\Program Files\Android\Android Studio\jbr'
if (-not $env:JAVA_HOME -and (Test-Path $jbr)) { $env:JAVA_HOME = $jbr }
if ((Test-Path $gradlew) -and $env:JAVA_HOME) {
  try { & $gradlew --stop 2>&1 | Out-Null } catch { }
}
Write-Host "Removed $($hits.Count) cache folders. Next Gradle build regenerates them."
